<?php
declare(strict_types=1);
namespace App\Services;
use App\Core\Database;use App\Core\Request;
class ChargeCategoryService{
 private function ensureRegistrationDefaults():void{$school=$this->school();if(!$school)return;$q=Database::connect()->prepare('INSERT IGNORE INTO charge_categories(school_id,code,label,default_amount,periodicity,status) VALUES(?,?,?,?,?,"ACTIVE")');foreach([['TRANSPORT','Transport',250,'MONTHLY'],['DAYCARE','Garde',120,'MONTHLY'],['SMOCK','Blouse',130,'ONE_TIME'],['PAPER','Ramettes',100,'CUSTOM'],['REGISTRATION_INSURANCE','Inscription + assurance',1100,'ONE_TIME']] as [$code,$label,$amount,$period])$q->execute([$school,$code,$label,$amount,$period]);}
 private function school():int{return(int)(Request::get('auth_user',[])['school_id']??0);}private function text(array$d,string$k):?string{$v=trim((string)($d[$k]??''));return$v?:null;}
 public function all(bool$active=false):array{$this->ensureRegistrationDefaults();$q='SELECT * FROM charge_categories WHERE school_id=?'.($active?' AND status="ACTIVE"':'').' ORDER BY label';$s=Database::connect()->prepare($q);$s->execute([$this->school()]);return$s->fetchAll();}
 public function one(int$id):array|false{$s=Database::connect()->prepare('SELECT * FROM charge_categories WHERE id=? AND school_id=?');$s->execute([$id,$this->school()]);return$s->fetch()?:false;}
 public function save(array$d,?int$id=null):array{$school=$this->school();if(!$school)return['error'=>'Établissement introuvable'];$label=$this->text($d,'label');$code=strtoupper((string)preg_replace('/[^A-Z0-9_]/','_',strtoupper($this->text($d,'code')??'')));$period=(string)($d['periodicity']??'ONE_TIME');$amount=array_key_exists('default_amount',$d)&&$d['default_amount']!==''?round((float)$d['default_amount'],2):null;if(!$label||!$code)return['error'=>'Le libellé et le code sont obligatoires'];if(!in_array($period,['MONTHLY','ANNUAL','ONE_TIME','SELECTED_MONTHS','CUSTOM'],true)||($amount!==null&&$amount<0))return['error'=>'Catégorie invalide'];$pdo=Database::connect();try{if($id){if(!$this->one($id))return['error'=>'Catégorie introuvable','status'=>404];$pdo->prepare('UPDATE charge_categories SET code=?,label=?,description=?,default_amount=?,periodicity=?,status=? WHERE id=? AND school_id=?')->execute([$code,$label,$this->text($d,'description'),$amount,$period,in_array($d['status']??'ACTIVE',['ACTIVE','ARCHIVED'],true)?$d['status']:'ACTIVE',$id,$school]);return['id'=>$id];}$pdo->prepare('INSERT INTO charge_categories(school_id,code,label,description,default_amount,periodicity)VALUES(?,?,?,?,?,?)')->execute([$school,$code,$label,$this->text($d,'description'),$amount,$period]);return['id'=>(int)$pdo->lastInsertId()];}catch(\PDOException){return['error'=>'Ce code de catégorie existe déjà'];}}
 public function archive(int$id):array{$c=$this->one($id);if(!$c)return['error'=>'Catégorie introuvable','status'=>404];Database::connect()->prepare('UPDATE charge_categories SET status="ARCHIVED" WHERE id=? AND school_id=?')->execute([$id,$this->school()]);return['id'=>$id,'status'=>'ARCHIVED'];}
}
